import { Injectable } from '@angular/core';
import { BaseStyle } from 'primeng/base';

const style = `
.p-progressspinner {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100px;
    height: 100px;
}

.p-progressspinner-circle {
    width: 100%;
    height: 100%;
}

.p-progressspinner-circle-track {
    stroke: dt('content.border.color');
}

.p-progressspinner-circle-range {
    stroke: dt('progressspinner.color.one');
    stroke-linecap: round;
    transition: stroke-dashoffset 0.3s;
}

[data-state="determinate"] .p-progressspinner-circle-range {
    transform: rotate(-90deg);
    transform-origin: center;
}

[data-state="indeterminate"] .p-progressspinner-circle {
    animation: p-progressspinner-rotate 2s linear infinite;
    transform-origin: center;
}

[data-state="indeterminate"] .p-progressspinner-circle-range {
    stroke-dasharray: 1, 302;
    stroke-dashoffset: 0;
    animation:
        p-progressspinner-dash 1.5s ease-in-out infinite,
        p-progressspinner-color 6s ease-in-out infinite;
}

.p-progressspinner-value {
    fill: dt('text.muted.color');
}

@keyframes p-progressspinner-rotate {
    100% {
        transform: rotate(360deg);
    }
}

@keyframes p-progressspinner-dash {
    0% {
        stroke-dasharray: 1, 302;
        stroke-dashoffset: 0;
    }
    50% {
        stroke-dasharray: 136, 302;
        stroke-dashoffset: -54px;
    }
    100% {
        stroke-dasharray: 1, 302;
        stroke-dashoffset: -302px;
    }
}

@keyframes p-progressspinner-color {
    100%,
    0% {
        stroke: dt('progressspinner.color.one');
    }
    40% {
        stroke: dt('progressspinner.color.two');
    }
    66% {
        stroke: dt('progressspinner.color.three');
    }
    80%,
    90% {
        stroke: dt('progressspinner.color.four');
    }
}
`;

const classes = {
    root: 'p-progressspinner',
    circle: 'p-progressspinner-circle',
    circleTrack: 'p-progressspinner-circle-track',
    circleRange: 'p-progressspinner-circle-range',
    value: 'p-progressspinner-value'
};

@Injectable()
export class ProgressSpinnerStyle extends BaseStyle {
    name = 'progressspinner';

    style = style;

    classes = classes;
}

/**
 *
 * ProgressSpinner is a process status indicator.
 *
 * [Live Demo](https://www.primeng.org/progressspinner)
 *
 * @module progressspinnerstyle
 *
 */
export enum ProgressSpinnerClasses {
    /**
     * Class name of the root element
     */
    root = 'p-progressspinner',
    /**
     * Class name of the circle element
     */
    circle = 'p-progressspinner-circle',
    /**
     * Class name of the circle track element
     */
    circleTrack = 'p-progressspinner-circle-track',
    /**
     * Class name of the circle range element
     */
    circleRange = 'p-progressspinner-circle-range',
    /**
     * Class name of the value element
     */
    value = 'p-progressspinner-value'
}
