import { ChangeDetectionStrategy, Component, computed, inject, InjectionToken, input, NgModule, numberAttribute, ViewEncapsulation } from '@angular/core';
import { SharedModule } from 'primeng/api';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import type { ProgressSpinnerPassThrough } from 'primeng/types/progressspinner';
import { ProgressSpinnerStyle } from './style/progressspinnerstyle';

const PROGRESSSPINNER_INSTANCE = new InjectionToken<ProgressSpinner>('PROGRESSSPINNER_INSTANCE');

/**
 * ProgressSpinner is a process status indicator.
 * @group Components
 */
@Component({
    selector: 'p-progress-spinner, p-progressspinner',
    standalone: true,
    imports: [SharedModule, Bind],
    template: `
        <svg [class]="cx('circle')" [pBind]="ptm('circle')" viewBox="0 0 100 100" [style.animation-duration]="animationDuration()">
            <circle [class]="cx('circleTrack')" [pBind]="ptm('circleTrack')" cx="50" cy="50" [attr.r]="_radius()" [attr.fill]="fill()" [attr.stroke-width]="strokeWidth()" />
            <circle
                [class]="cx('circleRange')"
                [pBind]="ptm('circleRange')"
                cx="50"
                cy="50"
                [attr.r]="_radius()"
                [attr.fill]="fill()"
                [attr.stroke-width]="strokeWidth()"
                [attr.stroke-dasharray]="indeterminate() ? null : _circumference()"
                [attr.stroke-dashoffset]="indeterminate() ? null : _dashOffset()"
            />
            @if (!indeterminate()) {
                <text [class]="cx('value')" [pBind]="ptm('value')" x="50" y="50" text-anchor="middle" dominant-baseline="central">{{ _displayPercent() }}%</text>
            }
        </svg>
    `,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [ProgressSpinnerStyle, { provide: PROGRESSSPINNER_INSTANCE, useExisting: ProgressSpinner }, { provide: PARENT_INSTANCE, useExisting: ProgressSpinner }],
    host: {
        '[attr.aria-label]': 'ariaLabel()',
        '[attr.role]': "'progressbar'",
        '[attr.aria-busy]': 'true',
        '[attr.data-state]': '_dataState()',
        '[attr.aria-valuemin]': '_ariaValueMin()',
        '[attr.aria-valuemax]': '_ariaValueMax()',
        '[attr.aria-valuenow]': '_ariaValueNow()',
        '[attr.data-value]': '_dataValue()',
        '[class]': "cx('root')"
    },
    hostDirectives: [Bind]
})
export class ProgressSpinner extends BaseComponent<ProgressSpinnerPassThrough> {
    componentName = 'ProgressSpinner';

    $pcProgressSpinner: ProgressSpinner | undefined = inject(PROGRESSSPINNER_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    /**
     * Current value of the progress. When null or undefined, the spinner is in indeterminate mode.
     * @defaultValue null
     * @group Props
     */
    value = input<number | null | undefined>(null);

    /**
     * Width of the circle stroke.
     * @defaultValue 4
     * @group Props
     */
    strokeWidth = input(4, { transform: numberAttribute });

    /**
     * Duration of the rotate animation.
     * @group Props
     */
    animationDuration = input('2s');

    /**
     * Minimum value.
     * @defaultValue 0
     * @group Props
     */
    min = input(0, { transform: numberAttribute });

    /**
     * Maximum value.
     * @defaultValue 100
     * @group Props
     */
    max = input(100, { transform: numberAttribute });

    /**
     * Used to define a aria label attribute the current element.
     * @group Props
     */
    ariaLabel = input<string>();

    /**
     * Color for the background of the circle.
     * @group Props
     */
    fill = input('none');

    _componentStyle = inject(ProgressSpinnerStyle);

    indeterminate = computed(() => this.value() == null);

    _radius = computed(() => (100 - this.strokeWidth()) / 2);

    _circumference = computed(() => 2 * Math.PI * this._radius());

    _clampedValue = computed(() => {
        if (this.indeterminate()) return 0;

        return Math.min(Math.max(this.value()!, this.min()), this.max());
    });

    _percent = computed(() => {
        if (this.indeterminate()) return 0;

        return ((this._clampedValue() - this.min()) / (this.max() - this.min())) * 100;
    });

    _dashOffset = computed(() => this._circumference() - (this._percent() / 100) * this._circumference());

    _displayPercent = computed(() => Math.round(this._percent()));

    _dataState = computed(() => (this.indeterminate() ? 'indeterminate' : 'determinate'));

    _dataValue = computed(() => (this.indeterminate() ? undefined : this._clampedValue()));

    _ariaValueMin = computed(() => (this.indeterminate() ? undefined : this.min()));

    _ariaValueMax = computed(() => (this.indeterminate() ? undefined : this.max()));

    _ariaValueNow = computed(() => (this.indeterminate() ? undefined : this._clampedValue()));

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }
}

@NgModule({
    imports: [ProgressSpinner, SharedModule],
    exports: [ProgressSpinner, SharedModule]
})
export class ProgressSpinnerModule {}
